// DeskFilter provides filtering for Desk queries
type DeskFilter struct {
	Id      *UUIDFilter
	Title   *StringFilter
	Version *Int64Filter
	// Bookings keeps the rows that some Booking row the filter
	// finds points at by its desk (D108, D180): one condition, the key
	// in the foreign keys of those rows.
	Bookings *BookingFilter
	// ReferencedByBookingDesk filters on the presence or absence of a
	// Booking whose desk points at this row.
	ReferencedByBookingDesk *ReferencedByFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []DeskFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []DeskFilter
}

// DeskUpdate provides fields that can be updated
type DeskUpdate struct {
	Title *string
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewDeskSnapshotUpdate maps every mutable field from a complete
// Desk value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewDeskSnapshotUpdate(input *types.Desk) *DeskUpdate {
	update := &DeskUpdate{}
	if input == nil {
		return update
	}
	update.Title = &input.Title
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *DeskUpdate) ApplyTo(row *types.Desk) {
	if u == nil || row == nil {
		return
	}
	if u.Title != nil {
		row.Title = *u.Title
	}
}

// DeskFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func DeskFilterConditions(filter *DeskFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a DeskFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *DeskFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

// conditions are the filter's conditions, each value appended to args, its
// placeholder numbered from paramOffset+1.
func (f *DeskFilter) conditions(args *[]interface{}, paramOffset int) []string {
	if f == nil {
		return nil
	}

	var conditions []string
	paramNum := paramOffset
	if f.Id != nil {
		if f.Id.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk.id = $%d`, paramNum))
			*args = append(*args, f.Id.Eq.ToUUID())
		}
		if f.Id.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk.id IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, f.Id.Ne.ToUUID())
		}
		if len(f.Id.In) > 0 {
			placeholders := make([]string, len(f.Id.In))
			for i, id := range f.Id.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`desk.id IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Id.NotIn) > 0 {
			placeholders := make([]string, len(f.Id.NotIn))
			for i, id := range f.Id.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`(desk.id IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Id.IsNull != nil {
			if *f.Id.IsNull {
				conditions = append(conditions, `desk.id IS NULL`)
			} else {
				conditions = append(conditions, `desk.id IS NOT NULL`)
			}
		}
	}
	if f.Title != nil {
		if f.Title.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk.title = $%d`, paramNum))
			*args = append(*args, *f.Title.Eq)
		}
		if f.Title.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk.title IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, *f.Title.Ne)
		}
		if len(f.Title.In) > 0 {
			placeholders := make([]string, len(f.Title.In))
			for i, value := range f.Title.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`desk.title IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Title.NotIn) > 0 {
			placeholders := make([]string, len(f.Title.NotIn))
			for i, value := range f.Title.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`(desk.title IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Title.ILike != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk.title ILIKE $%d`, paramNum))
			*args = append(*args, "%"+*f.Title.ILike+"%")
		}
		if f.Title.IsNull != nil {
			if *f.Title.IsNull {
				conditions = append(conditions, `desk.title IS NULL`)
			} else {
				conditions = append(conditions, `desk.title IS NOT NULL`)
			}
		}
	}
	if f.Version != nil {
		if f.Version.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version = $%d`, paramNum))
			*args = append(*args, *f.Version.Eq)
		}
		if f.Version.Ne != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version IS DISTINCT FROM $%d`, paramNum))
			*args = append(*args, *f.Version.Ne)
		}
		if f.Version.Gt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version > $%d`, paramNum))
			*args = append(*args, *f.Version.Gt)
		}
		if f.Version.Gte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version >= $%d`, paramNum))
			*args = append(*args, *f.Version.Gte)
		}
		if f.Version.Lt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version < $%d`, paramNum))
			*args = append(*args, *f.Version.Lt)
		}
		if f.Version.Lte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version <= $%d`, paramNum))
			*args = append(*args, *f.Version.Lte)
		}
		if f.Version.Between != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version >= $%d`, paramNum))
			*args = append(*args, f.Version.Between.Min)
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`desk._version <= $%d`, paramNum))
			*args = append(*args, f.Version.Between.Max)
		}
		if len(f.Version.In) > 0 {
			placeholders := make([]string, len(f.Version.In))
			for i, value := range f.Version.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`desk._version IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if len(f.Version.NotIn) > 0 {
			placeholders := make([]string, len(f.Version.NotIn))
			for i, value := range f.Version.NotIn {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`(desk._version IN (%s)) IS NOT TRUE`, strings.Join(placeholders, ", ")))
		}
		if f.Version.IsNull != nil {
			if *f.Version.IsNull {
				conditions = append(conditions, `desk._version IS NULL`)
			} else {
				conditions = append(conditions, `desk._version IS NOT NULL`)
			}
		}
	}
	if f.Bookings != nil {
		before := len(*args)
		through := f.Bookings.conditions(args, paramNum)
		paramNum += len(*args) - before
		where := ""
		if len(through) > 0 {
			where = " WHERE " + strings.Join(through, " AND ")
		}
		conditions = append(conditions, fmt.Sprintf(`desk.id IN (SELECT booking.desk_id FROM booking%s)`, where))
	}
	if f.ReferencedByBookingDesk != nil {
		probe := `SELECT 1 FROM booking WHERE booking.desk_id = desk.id`
		if f.ReferencedByBookingDesk.Exists {
			conditions = append(conditions, fmt.Sprintf(`EXISTS (%s)`, probe))
		} else {
			conditions = append(conditions, fmt.Sprintf(`NOT EXISTS (%s)`, probe))
		}
	}

	// AllOf's filters' conditions are the filter's own, ANDed (D99), each
	// one's placeholders numbered after the last.
	for i := range f.AllOf {
		before := len(*args)
		conditions = append(conditions, f.AllOf[i].conditions(args, paramNum)...)
		paramNum += len(*args) - before
	}

	if len(f.AnyOf) > 0 {
		start := len(*args)
		branches := make([]string, 0, len(f.AnyOf))
		every := false
		for i := range f.AnyOf {
			before := len(*args)
			branch := f.AnyOf[i].conditions(args, paramNum)
			paramNum += len(*args) - before
			if len(branch) == 0 {
				every = true
				continue
			}
			branches = append(branches, "("+strings.Join(branch, " AND ")+")")
		}
		if every {
			// A branch of no condition keeps every row, and so does the
			// whole: the other branches' parameters go too. AnyOf is the
			// last condition, so no placeholder follows theirs.
			*args = (*args)[:start]
		} else {
			conditions = append(conditions, "("+strings.Join(branches, " OR ")+")")
		}
	}

	return conditions
}
